return [
    'page_title' => 'નિયમો અને શરતો',
    'last_updated' => 'છેલ્લે અપડેટ :date',
    's1_title' => '1. આ નિયમો સાથે સંમતિ.',
    's1_body' => 'આ નિયમો અને શરતો ("નિયમો") અમારી વેબસાઇટ, મોબાઇલ અનુભવ અને સંબંધિત તમામ ખાતા, ચુકવણી, કાર્ડ અને સહાય સુવિધાઓ (સંયુક્ત રીતે, "સેવા") સહિત Ledger ની તમારી ઍક્સેસ અને ઉપયોગને નિયંત્રિત કરે છે. ખાતું બનાવીને કે સેવાનો ઉપયોગ કરીને, તમે આ નિયમો અને તેમાં ઉલ્લેખિત કોઈપણ નીતિઓથી બંધાયેલા રહેવા સંમત થાઓ છો. તમે સંમત ન હો તો ખાતું ન બનાવો અને સેવાનો ઉપયોગ ન કરો.',
    's2_title' => '2. પાત્રતા.',
    's2_body' => 'Ledger ખાતું ખોલવા અને રાખવા માટે તમારી ઉંમર ઓછામાં ઓછી 18 વર્ષ હોવી જોઈએ, તમે બંધનકર્તા કરાર કરવા સક્ષમ હોવા જોઈએ, અને માંગવામાં આવે ત્યારે સરકાર દ્વારા જારી કરાયેલ માન્ય ઓળખ દસ્તાવેજ અને કાયમી રહેઠાણનું સરનામું આપી શકવા જોઈએ. અમે તમારી ઓળખ ચકાસી ન શકીએ, તમે સરકારી પ્રતિબંધ કે દેખરેખ સૂચિમાં હો, અથવા ખાતું ખોલવું કે રાખવું Ledger ને કાનૂની કે નિયમનકારી જોખમમાં મૂકે, તો અમે ખાતું ખોલવાનો ઇનકાર કરી શકીએ અથવા હાલનું ખાતું બંધ કરી શકીએ.',
    's3_title' => '3. તમારું ખાતું.',
    's3_body' => 'Ledger ખાતાનું બેલેન્સ Ledger બેંક તરીકે સીધું રાખતું નથી. ભંડોળ એક કે વધુ FDIC-વીમાકૃત ભાગીદાર બેંકોમાં સંયુક્ત કસ્ટોડિયલ ખાતાઓમાં રખાય છે, અને તમારું ભંડોળ લાગુ મર્યાદા સુધી FDIC ના "પાસ-થ્રુ" થાપણ વીમા માટે પાત્ર છે; આ FDIC નિયમો, તે જ ભાગીદાર બેંકમાં તમારા અન્ય ભંડોળ સાથેના એકત્રીકરણ અને ભાગીદાર બેંકની નિષ્ફળતાને આધીન છે. Ledger પોતે એક નાણાકીય ટેક્નોલોજી કંપની છે, લાઇસન્સવાળી બેંક નથી. લેખિતમાં અન્યથા સંમત ન થઈએ ત્યાં સુધી તમે ફક્ત એક વ્યક્તિગત ખાતું રાખી શકો છો, અને અમારી પૂર્વ લેખિત સંમતિ વિના કોઈ વ્યવસાય, ટ્રસ્ટ કે અન્ય વ્યક્તિ વતી ભંડોળ સ્વીકારવા ખાતાનો ઉપયોગ કરી શકાતો નથી.',
    's4_title' => '4. ઓળખ ચકાસણી અને ખાતા મર્યાદાઓ.',
    's4_body' => 'સંઘીય કાયદો નાણાકીય સેવા પ્રદાતાઓને ખાતું ખોલનાર દરેક વ્યક્તિની ઓળખ કરતી માહિતી મેળવવા, ચકાસવા અને નોંધવા ફરજિયાત બનાવે છે. અમે તમને ફોટો ઓળખ દસ્તાવેજ, સેલ્ફી કે સરનામાનો પુરાવો સબમિટ કરવા કહી શકીએ, અને તે માહિતીની સમીક્ષા થઈ મંજૂર ન થાય ત્યાં સુધી ટ્રાન્સફર રકમ, કાર્ડ જારી કરવા કે અન્ય સુવિધાઓ મર્યાદિત કરી શકીએ. અમે સમયાંતરે તમારી માહિતી ફરી ચકાસી શકીએ અને અપડેટ માહિતીની વિનંતીનો જવાબ ન મળે તો અસરગ્રસ્ત સુવિધાઓ મોકૂફ કરી શકીએ.',
    's5_title' => '5. ટ્રાન્સફર અને ચુકવણી.',
    's5_body' => 'સેવા પૈસા ખસેડવાની ઘણી રીતોને સમર્થન આપે છે, દરેક વ્યવહાર સમયે બતાવેલી મર્યાદાઓ, કટ-ઑફ સમય અને સમીક્ષાને આધીન છે: (ક) Ledger થી Ledger ટ્રાન્સફર, Ledger ખાતાઓ વચ્ચે તરત મોકલાય છે; (ખ) બાહ્ય બેંક ટ્રાન્સફર, તે જ દેશની લિંક કરેલી કે પસંદ કરેલી બેંકને તે બેંકની રાઉટિંગ માહિતીથી મોકલાય છે; (ગ) આંતરરાષ્ટ્રીય ટ્રાન્સફર, તમારા દેશ બહારની બેંકને તેના SWIFT/BIC કોડ અને ખાતા કે IBAN નંબરથી મોકલાય છે, જે પહોંચવામાં વધુ સમય લઈ શકે, અમારા નિયંત્રણ બહારની મધ્યસ્થી બેંકોમાંથી પસાર થઈ શકે અને ટ્રાન્સફર પર પ્રક્રિયા થાય ત્યારે નક્કી થયેલા દરે ચલણ રૂપાંતરણને આધીન હોઈ શકે; (ઘ) બિલ ચુકવણી, તમે નિયુક્ત કરેલા પ્રાપ્તકર્તાને મોકલાય છે; અને (ચ) ઉપાડ અને ટોપ-અપ, જે તમારા Ledger બેલેન્સ અને લિંક કરેલા કાર્ડ કે બાહ્ય ખાતા વચ્ચે પૈસા ખસેડે છે. પ્રાપ્તકર્તા, રાઉટિંગ, SWIFT/BIC અને ખાતાની વિગતો સંપૂર્ણ અને સચોટ દાખલ કરવાની જવાબદારી તમારી છે — તમે આપેલી વિગતો પર યોગ્ય રીતે મોકલાયેલું ટ્રાન્સફર, તે વિગતો ખોટી હોય તોપણ, Ledger પાછું વાળી શકતું નથી. શંકાસ્પદ છેતરપિંડી, પ્રતિબંધ તપાસ કે અપૂરતા ઉપલબ્ધ બેલેન્સને કારણે ચિહ્નિત થાય તો ટ્રાન્સફરમાં વિલંબ થઈ શકે, સમીક્ષા માટે અટકાવી શકાય કે નકારી શકાય.',
    's6_title' => '6. શેડ્યૂલ કરેલાં ટ્રાન્સફર.',
    's6_body' => 'ભવિષ્યની તારીખ માટે શેડ્યૂલ કરેલું ટ્રાન્સફર ફક્ત પસંદ કરેલી તારીખે જ સબમિટ થાય છે અને તે ખરેખર તમારા બેલેન્સમાંથી જાય નહીં ત્યાં સુધી ગેરંટી નથી. તે તારીખ પહેલાં ક્યારેય પણ ખાતાના ઇતિહાસમાંથી તમે શેડ્યૂલ કરેલું ટ્રાન્સફર રદ કરી શકો છો. શેડ્યૂલ કરેલી તારીખે ઉપલબ્ધ બેલેન્સ અપૂરતું હોય તો ટ્રાન્સફર નિષ્ફળ જશે અને ઇતિહાસમાં તે મુજબ ચિહ્નિત થશે; પૂરતું ભંડોળ ઉપલબ્ધ છે તેની ખાતરી કરવી તમારી જવાબદારી છે.',
    's7_title' => '7. ફી.',
    's7_body' => 'સેવા દ્વારા શરૂ કરાયેલા Ledger થી Ledger ટ્રાન્સફર, બાહ્ય બેંક ટ્રાન્સફર, આંતરરાષ્ટ્રીય ટ્રાન્સફર, ઉપાડ કે ટોપ-અપ માટે Ledger હાલ કોઈ ફી લેતું નથી. તમારી લિંક કરેલી બેંક, કાર્ડ જારીકર્તા કે પ્રાપ્ત કરતી આંતરરાષ્ટ્રીય બેંક હજી પણ પોતાની ફી લગાવી શકે — આંતરરાષ્ટ્રીય ટ્રાન્સફર પર ચલણ રૂપાંતરણ, વાયર કે મધ્યસ્થી બેંક ફી સહિત — જે અમારા નિયંત્રણ બહાર છે અને Ledger વસૂલતું કે રાખતું નથી. ભવિષ્યમાં Ledger કોઈ સુવિધા માટે ફી શરૂ કરે, તો વ્યવહારની પુષ્ટિ કરતા પહેલાં તે તમને જણાવાશે, અને તેનું વર્ણન કરવા આ નિયમો અપડેટ કરાશે.',
    's8_title' => '8. કાર્ડ.',
    's8_body' => 'તમે તમારા Ledger બેલેન્સ સાથે લિંક કરેલા વર્ચ્યુઅલ કે ભૌતિક ડેબિટ કાર્ડની વિનંતી કરો, તો તે કાર્ડ મંજૂરીને આધીન છે અને જારી થયા પછી દરેક ખરીદી સમયે સીધું તમારા ઉપલબ્ધ બેલેન્સમાંથી કપાય છે — આ ક્રેડિટ લાઇન નથી. ખોવાયેલું, ચોરાયેલું કે જોખમગ્રસ્ત કાર્ડ સ્થગિત કે બંધ કરવા કાર્ડ પૃષ્ઠ દ્વારા તરત જાણ કરવી જ પડશે; જાણ મળે તે પહેલાં થયેલા વ્યવહારો માટે તમે જવાબદાર રહો છો, લાગુ કાયદો અને નીચેની કલમ 10 મર્યાદિત કરે તે સિવાય.',
    's9_title' => '9. તમારી જવાબદારીઓ અને ખાતાની સુરક્ષા.',
    's9_body' => 'તમારો પાસવર્ડ, વ્યવહાર PIN, દ્વિ-પરિબળ પ્રમાણીકરણ કોડ અને Ledger વાપરવા માટેનું ઉપકરણ સુરક્ષિત રાખવાની અને તેને કોઈ સાથે શેર ન કરવાની જવાબદારી તમારી છે. તમારું ખાતું, પાસવર્ડ કે કાર્ડ જોખમમાં હોવાનું લાગે, અથવા તમે ન ઓળખતા હો તેવો વ્યવહાર દેખાય, તો સહાય પૃષ્ઠ દ્વારા તરત અમને જાણ કરવી જ પડશે. તમે તમારી સંપર્ક માહિતી, ટપાલ સરનામું અને રેકોર્ડ પરના ઓળખ દસ્તાવેજો અપડેટ અને સચોટ રાખવા સંમત થાઓ છો.',
    's10_title' => '10. ભૂલો અને અનધિકૃત વ્યવહારો.',
    's10_body' => 'કોઈ ટ્રાન્સફર, કાર્ડ ચાર્જ કે અન્ય વ્યવહાર તમારી પરવાનગી વિના થયો હોવાનું, અથવા તમારા ખાતા સ્ટેટમેન્ટમાં ભૂલ હોવાનું લાગે, તો શક્ય તેટલું વહેલું અને પ્રવૃત્તિ ઇતિહાસમાં પહેલી વાર દેખાયાના 60 દિવસની અંદર સહાયનો સંપર્ક કરો. અમે પ્રામાણિકપણે તપાસ કરીશું અને તપાસ ચાલુ હોય ત્યારે કામચલાઉ ભંડોળ પરત કરી શકીએ. પુષ્ટિ થયેલા અનધિકૃત વ્યવહાર માટે તમારી જવાબદારી લાગુ કાયદો માંગે તેટલી મર્યાદિત છે, જો તમે તરત અમને જાણ કરો અને તમારી લૉગિન વિગતોના રક્ષણમાં છેતરપિંડી કે ઘોર બેદરકારી ન દાખવી હોય.',
    's11_title' => '11. પ્રતિબંધિત ઉપયોગ.',
    's11_body' => 'તમે સંમત થાઓ છો કે મની લૉન્ડરિંગ, આતંકવાદને નાણાં, છેતરપિંડી કે પ્રતિબંધો ટાળવા સહિત કોઈ ગેરકાયદે હેતુ માટે સેવાનો ઉપયોગ નહીં કરો; કાયદેસર રીતે હકદાર ન હો તેવું ભંડોળ મોકલશો કે મેળવશો નહીં; અન્ય વપરાશકર્તાના ખાતા કે Ledger ની સિસ્ટમમાં અનધિકૃત ઍક્સેસનો પ્રયાસ નહીં કરો; અને સેવાના સામાન્ય સંચાલનમાં દખલ નહીં કરો. આ કલમનું ઉલ્લંઘન કરે છે એવું વાજબી રીતે માનવામાં આવે તેવો કોઈપણ વ્યવહાર અમે નકારી, વિલંબિત, શક્ય હોય ત્યાં પાછો વાળી કે જાણ કરી શકીએ, અને કાયદા મુજબ કાયદા અમલીકરણ કે નિયમનકારો સાથે માહિતી શેર કરી શકીએ.',
    's12_title' => '12. ખાતાની સ્થિતિ, મોકૂફી અને બંધ.',
    's12_body' => 'અમારી વિવેકબુદ્ધિથી અમે તમારું ખાતું સ્થગિત, મર્યાદિત, મોકૂફ કે બંધ કરી શકીએ, અથવા ચોક્કસ વ્યવહાર નકારી શકીએ — કાયદાનું પાલન કરવા, શંકાસ્પદ છેતરપિંડી કે દુરુપયોગની તપાસ કરવા, કાનૂની કે નિયમનકારી વિનંતીનો જવાબ આપવા, અથવા તમારું, અન્ય વપરાશકર્તાનું કે Ledger નું રક્ષણ કરવા જરૂરી હોવાનું વાજબી રીતે માનીએ ત્યારે સહિત. શક્ય હોય ત્યાં અમે કારણ અને સહાય પૃષ્ઠ દ્વારા અમારો સંપર્ક કેવી રીતે કરવો તે જણાવીશું. તમારું બેલેન્સ શૂન્ય કે ઉપાડેલું હોય અને કોઈ ખુલ્લી તપાસ કે બાકી વ્યવહાર ન હોય, તો સહાયનો સંપર્ક કરીને તમે ક્યારેય પણ ખાતું બંધ કરી શકો છો.',
    's13_title' => '13. સેવાની ઉપલબ્ધતા; અસ્વીકરણ.',
    's13_body' => 'સેવા ઉપલબ્ધ અને સચોટ રાખવા અમે કામ કરીએ છીએ, પરંતુ સેવા "જેમ છે તેમ" પૂરી પાડવામાં આવે છે અને તે હંમેશાં અવિરત, ભૂલરહિત કે ઉપલબ્ધ રહેશે તેવી ગેરંટી અમે આપતા નથી. ભાગીદાર બેંક, કાર્ડ નેટવર્ક કે મધ્યસ્થી સંસ્થામાં વિક્ષેપ, અથવા અણધારી ઘટનાઓ સહિત અમારા વાજબી નિયંત્રણ બહારના સંજોગોને કારણે થતા વિલંબ કે નિષ્ફળતા માટે અમે જવાબદાર નથી. કાયદો પરવાનગી આપે તેટલી પૂર્ણ હદ સુધી, સેવાના ઉપયોગથી ઊભા થતા કોઈપણ દાવા માટે Ledger ની કુલ જવાબદારી તે દાવાનું કારણ બનેલા વ્યવહારની રકમ સુધી મર્યાદિત છે, સિવાય કે ગ્રાહકોના નાણાકીય ખાતાઓનું રક્ષણ કરતો કાયદો વ્યાપક ઉપાય માંગે.',
    's14_title' => '14. વિવાદ નિરાકરણ.',
    's14_body' => 'તમારી અને Ledger વચ્ચે મતભેદ થાય, તો સીધું ઉકેલવાનો પ્રયાસ કરવા પહેલા સહાયનો સંપર્ક કરવા અમે વિનંતી કરીએ છીએ — મોટાભાગની સમસ્યાઓ આ રીતે જ ઉકેલાય છે. વિવાદ અનૌપચારિક રીતે ન ઉકેલાય, તો કોઈપણ પક્ષ લાગુ કાયદા હેઠળ ઉપલબ્ધ કોઈપણ ઉપાય માંગી શકે છે. આ નિયમોમાંનું કંઈ પણ ગ્રાહક સુરક્ષા કાયદા હેઠળ તમારા રાજ્ય કે સંઘીય નિયમનકાર સમક્ષ વિવાદ ઉઠાવવાના તમારા અધિકારને મર્યાદિત કરતું નથી.',
    's15_title' => '15. ગોપનીયતા.',
    's15_body' => 'તમારી વ્યક્તિગત અને નાણાકીય માહિતી અમે કેવી રીતે સંભાળીએ છીએ — અમે શું એકત્ર કરીએ છીએ, તેનો ઉપયોગ કેવી રીતે કરીએ છીએ, કોની સાથે શેર કરી શકીએ (જેમ કે ભાગીદાર બેંકો, ઓળખ ચકાસણી પ્રદાતાઓ અને સેવા ચલાવવા જરૂરી કાર્ડ નેટવર્ક), અને તમારી પાસે કયા વિકલ્પો છે — તે અમારી ગોપનીયતા પદ્ધતિઓમાં વર્ણવેલું છે. અમે તમારી ઓળખ અને ખાતાની માહિતીનો ઉપયોગ ફક્ત સેવા ચલાવવા, સુરક્ષિત રાખવા અને તેને લાગુ કાયદાનું પાલન કરવા કરીએ છીએ, અને તમારી વ્યક્તિગત માહિતી વેચતા નથી.',
    's16_title' => '16. આ નિયમોમાં ફેરફાર.',
    's16_body' => 'સેવા, અમારી ભાગીદાર બેંકો કે લાગુ કાયદામાં થયેલા ફેરફારો પ્રતિબિંબિત કરવા અમે સમયાંતરે આ નિયમો અપડેટ કરી શકીએ. મહત્ત્વપૂર્ણ ફેરફાર કરીએ ત્યારે ઉપરની "છેલ્લે અપડેટ" તારીખ અપડેટ કરીશું અને કાયદો માંગે ત્યાં વધારાની સૂચના આપીશું. ફેરફાર અમલમાં આવ્યા પછી સેવાનો ઉપયોગ ચાલુ રાખવાનો અર્થ છે કે તમે અપડેટ થયેલા નિયમો સ્વીકારો છો; ફેરફાર સાથે સંમત ન હો તો સેવાનો ઉપયોગ બંધ કરી ખાતું બંધ કરવું જોઈએ.',
    's17_title' => '17. લાગુ કાયદો.',
    's17_body' => 'કાયદાના સંઘર્ષના સિદ્ધાંતોને ધ્યાનમાં લીધા વિના, આ નિયમો યુનાઇટેડ સ્ટેટ્સના કાયદાઓ અને Ledger ના કામકાજનું મુખ્યાલય જે રાજ્યમાં છે તેના કાયદાઓ દ્વારા નિયંત્રિત છે, સિવાય કે તમે જ્યાં રહો છો તે અધિકારક્ષેત્ર અલગ કાયદો લાગુ કરવાનું ફરજિયાત કરે.',
    's18_title' => '18. અમારો સંપર્ક કરો.',
    's18_body' => 'આ નિયમો, તમારા ખાતા કે ચોક્કસ વ્યવહાર વિશેના પ્રશ્નો :support_link પૃષ્ઠ દ્વારા ક્યારેય પણ મોકલી શકાય છે.',
    'support_link_text' => 'સહાય',
];
